commands.command:
RP=$(cat /root/.branch-ledger-repl-password)
mariadb --protocol=socket <<ANTRIEB_SQL
SOURCE /srv/legacy2/mysql-replication-catchup/ledger.sql;
STOP SLAVE;
RESET SLAVE ALL;
CHANGE MASTER TO MASTER_HOST='10.100.149.10', MASTER_PORT=3306, MASTER_USER='ledger_repl', MASTER_PASSWORD=[REDACTED]]], MASTER_LOG_FILE='mariadb-bin.000001', MASTER_LOG_POS=1396, MASTER_CONNECT_RETRY=2;
START SLAVE;
ANTRIEB_SQL
unset RP
for i in $(seq 1 15); do S=$(mariadb --protocol=socket -NBe "SHOW SLAVE STATUS" | awk -F '\t' '{print $11 "/" $12 "/" $33}'); [ "$S" = 'Yes/Yes/0' ] && break; sleep 1; done
mariadb --protocol=socket -e "SHOW SLAVE STATUS\G; SELECT id, amount FROM branch_ledger.entries ORDER BY id; SELECT @@read_only AS read_only, @@server_id AS server_id;"
sha256sum /srv/legacy2/mysql-replication-catchup/ledger.sql

umask 077; printf '%s\n%s\n' 'branch-ledger-write-probe-v1' "$CLUSTER_SSH_PRIVKEY" | sha256sum | awk '{print $1}' > /root/.branch-ledger-probe-password; PW=$(cat /root/.branch-ledger-probe-password); mariadb --protocol=socket <<ANTRIEB_SQL
DROP USER IF EXISTS 'write_probe'@'localhost';
CREATE USER 'write_probe'@'localhost' IDENTIFIED BY [REDACTED]
GRANT SELECT,INSERT ON branch_ledger.entries TO 'write_probe'@'localhost';
ANTRIEB_SQL
printf '%s\n' '--- application read succeeds ---'; MYSQL_PWD="$PW" mariadb --protocol=socket --user=write_probe -e "SELECT COUNT(*) AS readable_rows FROM branch_ledger.entries"; printf '%s\n' '--- application write is rejected ---'; set +e; MYSQL_PWD="$PW" mariadb --protocol=socket --user=write_probe -e "INSERT INTO branch_ledger.entries VALUES (1999,1.00)" 2>&1; RC=$?; set -e; printf 'write_exit_code=%s\n' "$RC"; mariadb --protocol=socket -e "DROP USER 'write_probe'@'localhost'; SELECT @@read_only AS replica_read_only, COUNT(*) AS rows_after_rejected_write FROM branch_ledger.entries;"; rm -f /root/.branch-ledger-probe-password; unset PW
